content.text:
{
  "name": "TFMini 距离传感器",
  "name_en": "TFMini distance sensor",
  "manufacturer": "",
  "description": "TFMini/TFMini-Plus 距离传感器，用于在实验装置或移动平台中测量目标距离，并输出以厘米为单位的距离读数。该设备支持轮询、持续更新、线程化读取和安全关闭连接。",
  "description_en": "A TFMini/TFMini-Plus distance sensor used to measure target distance in lab setups or mobile platforms, returning distance readings in centimeters. The device supports polling, continuous updating, threaded reading, and safe shutdown of the connection.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "持续更新传感器的距离读数。",
      "description_en": "Continuously update the sensor distance reading."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询传感器并获取当前距离。",
      "description_en": "Poll the sensor and obtain the current distance."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程模式下返回最近一次距离读数。",
      "description_en": "Return the most recent distance reading in threaded mode."
    },
    {
      "action_name": "auto-run",
      "description": "读取并返回当前距离测量值。",
      "description_en": "Read and return the current distance measurement."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭传感器连接。",
      "description_en": "Shut down the sensor connection."
    }
  ],
  "tag_hints": [
    "distance sensing",
    "rangefinding",
    "TFMini",
    "TFMini-Plus",
    "centimeter distance output",
    "serial sensor"
  ]
}

